#[tokio::test]
#[ignore] // ��Ҫ Docker ����
async fn test_field_permission_sort() {
    let (pool, db) = setup_test_env!();

    // �������Ա�
    create_test_users_table(&db).await.unwrap();

    let table_config = create_test_users_table_config_with_permissions();

    // �û���ɫ���԰� name �ֶ�����
    let query = TableQuery::new(
        table_config.clone(),
        vec!["user".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let result = query.order_by("name", SortOrder::Asc);
    assert!(result.is_ok(), "�û���ɫӦ�ÿ��԰� name �ֶ�����");

    // �û���ɫ���ܰ� email �ֶ�����ֻ�� admin ���ԣ�
    let query = TableQuery::new(
        table_config.clone(),
        vec!["user".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let result = query.order_by("email", SortOrder::Asc);
    assert!(result.is_err(), "�û���ɫ��Ӧ���ܰ� email �ֶ�����");

    // admin ��ɫ���԰������ֶ�����
    let query = TableQuery::new(
        table_config,
        vec!["admin".to_string()],
        Some(Arc::new(pool)),
    );

    let result = query.order_by("email", SortOrder::Asc);
    assert!(result.is_ok(), "admin ��ɫӦ�ÿ��԰������ֶ�����");
}

