async fn test_paginate_query_with_conditions() {
    let (pool, db) = setup_test_env!();

    // �������Ա�
    create_test_users_table(&db).await.unwrap();

    // ����������ݣ�50 ����¼��
    for i in 1..=50 {
        let status = if i % 2 == 0 { "active" } else { "inactive" };
        db.execute(&format!(
            "INSERT INTO test_users (name, email, age, status) VALUES ('User{}', 'user{}@example.com', {}, '{}')",
            i, i, 20 + (i % 30), status
        ))
        .await
        .unwrap();
    }

    let table_config = create_test_users_table_config();

    // ִ�д������ķ�ҳ��ѯ��status = 'active'
    let query = TableQuery::new(
        table_config,
        vec!["admin".to_string()],
        Some(Arc::new(pool)),
    );

    let result: PaginatedResult<TestUser> = query
        .where_eq("status", serde_json::json!("active"))
        .unwrap()
        .order_by("id", SortOrder::Asc)
        .unwrap()
        .page(1, 10)
        .unwrap()
        .paginate()
        .await
        .unwrap();

    // ��֤���
    assert_eq!(result.total, 25, "�ܼ�¼��Ӧ���� 25��ֻ��һ���� active��");
    assert_eq!(result.page, 1, "��ǰҳӦ���� 1");
    assert_eq!(result.page_size, 10, "ÿҳ��СӦ���� 10");
    assert_eq!(result.total_pages, 3, "��ҳ��Ӧ���� 3");
    assert_eq!(result.data.len(), 10, "��ǰҳ��������Ӧ���� 10");

    // ��֤���з��صļ�¼����������
    for user in &result.data {
        assert_eq!(user.status, "active", "���м�¼�� status Ӧ�õ��� active");
    }
}
