/// ���������� CRUD ����
///
/// **��֤����**: 5.6, 5.8, 5.9, 5.10
#[tokio::test]
#[ignore] // ��Ҫ Docker ����
async fn test_crud_complete_flow() {
    let (pool, db) = setup_test_env!();

    // �������Ա�
    create_test_users_table(&db).await.unwrap();

    let table_config = create_test_users_table_config();

    // 1. INSERT - ʹ��ԭ�� SQL �������ݣ��ƹ� TableQuery �� INSERT��
    db.execute(
        "INSERT INTO test_users (name, email, age, status) VALUES ('����', 'zhangsan@example.com', 25, 'active')"
    )
    .await
    .unwrap();

    // 2. SELECT - ��ѯ����
    let query = TableQuery::new(
        table_config.clone(),
        vec!["admin".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let users: Vec<TestUser> = query
        .where_eq("name", serde_json::json!("����"))
        .unwrap()
        .select()
        .await
        .unwrap();

    assert_eq!(users.len(), 1, "Ӧ�ò�ѯ�� 1 ����¼");
    assert_eq!(users[0].name, "����");
    assert_eq!(users[0].email, "zhangsan@example.com");
    assert_eq!(users[0].age, 25);
    assert_eq!(users[0].status, "active");

    let user_id = users[0].id;

    // 3. UPDATE - ��������
    let query = TableQuery::new(
        table_config.clone(),
        vec!["admin".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let mut update_data = HashMap::new();
    update_data.insert("age".to_string(), serde_json::json!(26));
    update_data.insert("status".to_string(), serde_json::json!("inactive"));

    let affected = query
        .where_eq("id", serde_json::json!(user_id))
        .unwrap()
        .update(update_data)
        .await
        .unwrap();

    assert_eq!(affected, 1, "����Ӧ��Ӱ�� 1 ��");

    // ��֤���½��
    let query = TableQuery::new(
        table_config.clone(),
        vec!["admin".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let users: Vec<TestUser> = query
        .where_eq("id", serde_json::json!(user_id))
        .unwrap()
        .select()
        .await
        .unwrap();

    assert_eq!(users[0].age, 26, "����Ӧ�ø���Ϊ 26");
    assert_eq!(users[0].status, "inactive", "״̬Ӧ�ø���Ϊ inactive");

    // 4. DELETE - ɾ�����ݣ�����ɾ����
    let query = TableQuery::new(
        table_config.clone(),
        vec!["admin".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let affected = query
        .where_eq("id", serde_json::json!(user_id))
        .unwrap()
        .delete()
        .await
        .unwrap();

    assert_eq!(affected, 1, "ɾ��Ӧ��Ӱ�� 1 ��");

    // ��֤ɾ�����
    let query = TableQuery::new(
        table_config,
        vec!["admin".to_string()],
        Some(Arc::new(pool)),
    );

    let users: Vec<TestUser> = query
        .where_eq("id", serde_json::json!(user_id))
        .unwrap()
        .select()
        .await
        .unwrap();

    assert_eq!(users.len(), 0, "��¼Ӧ�ñ�ɾ��");
}

