/// ���Է�ҳ��ѯ����
///
/// **��֤����**: 5.7
#[tokio::test]
#[ignore] // ��Ҫ Docker ����
async fn test_paginate_query() {
    let (pool, db) = setup_test_env!();

    // �������Ա�
    create_test_users_table(&db).await.unwrap();

    // ����������ݣ�30 ����¼��
    for i in 1..=30 {
        db.execute(&format!(
            "INSERT INTO test_users (name, email, age, status) VALUES ('User{}', 'user{}@example.com', {}, 'active')",
            i, i, 20 + (i % 20)
        ))
        .await
        .unwrap();
    }

    let table_config = create_test_users_table_config();

    // ִ�з�ҳ��ѯ���� 1 ҳ��ÿҳ 10 ��
    let query = TableQuery::new(
        table_config.clone(),
        vec!["admin".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let result: PaginatedResult<TestUser> = query.page(1, 10).unwrap().paginate().await.unwrap();

    // ��֤���
    assert_eq!(result.total, 30, "�ܼ�¼��Ӧ���� 30");
    assert_eq!(result.page, 1, "��ǰҳӦ���� 1");
    assert_eq!(result.page_size, 10, "ÿҳ��СӦ���� 10");
    assert_eq!(result.total_pages, 3, "��ҳ��Ӧ���� 3");
    assert_eq!(result.data.len(), 10, "��ǰҳ��������Ӧ���� 10");
    assert!(result.has_next(), "Ӧ������һҳ");
    assert!(!result.has_prev(), "��Ӧ������һҳ");

    // ִ�з�ҳ��ѯ���� 2 ҳ
    let query = TableQuery::new(
        table_config.clone(),
        vec!["admin".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let result: PaginatedResult<TestUser> = query.page(2, 10).unwrap().paginate().await.unwrap();

    assert_eq!(result.page, 2, "��ǰҳӦ���� 2");
    assert_eq!(result.data.len(), 10, "��ǰҳ��������Ӧ���� 10");
    assert!(result.has_next(), "Ӧ������һҳ");
    assert!(result.has_prev(), "Ӧ������һҳ");

    // ִ�з�ҳ��ѯ���� 3 ҳ�����һҳ��
    let query = TableQuery::new(
        table_config,
        vec!["admin".to_string()],
        Some(Arc::new(pool)),
    );

    let result: PaginatedResult<TestUser> = query.page(3, 10).unwrap().paginate().await.unwrap();

    assert_eq!(result.page, 3, "��ǰҳӦ���� 3");
    assert_eq!(result.data.len(), 10, "��ǰҳ��������Ӧ���� 10");
    assert!(!result.has_next(), "��Ӧ������һҳ");
    assert!(result.has_prev(), "Ӧ������һҳ");
}

