/// �����ֶ�д��Ȩ��
///
/// **��֤����**: 5.18, 5.20
#[tokio::test]
#[ignore] // ��Ҫ Docker ����
async fn test_field_permission_write() {
    let (pool, db) = setup_test_env!();

    // �������Ա�
    create_test_users_table(&db).await.unwrap();

    let table_config = create_test_users_table_config_with_permissions();

    // �û���ɫ����д�� name �ֶΣ�ֻ�� admin ���ԣ�
    // ע�⣺���� INSERT ���ܿ��������⣬����ֻ������֤�߼�
    // ������������ʵ�ʵ� INSERT ���ԣ�ֻ���� UPDATE Ȩ��

    // �Ȳ���һ����������
    db.execute(
        "INSERT INTO test_users (name, email, age, status) VALUES ('����', 'zhangsan@example.com', 25, 'active')"
    )
    .await
    .unwrap();

    // ��ѯ���������
    let query = TableQuery::new(
        table_config.clone(),
        vec!["admin".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let users: Vec<TestUser> = query
        .where_eq("name", serde_json::json!("����"))
        .unwrap()
        .select()
        .await
        .unwrap();

    let user_id = users[0].id;

    // �û���ɫ���ܸ��� name �ֶΣ�ֻ�� admin ���ԣ�
    let query = TableQuery::new(
        table_config.clone(),
        vec!["user".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let mut update_data = HashMap::new();
    update_data.insert("name".to_string(), serde_json::json!("����"));

    let result = query
        .where_eq("id", serde_json::json!(user_id))
        .unwrap()
        .update(update_data)
        .await;
    assert!(result.is_err(), "�û���ɫ��Ӧ����д�� name �ֶ�");

    // admin ��ɫ���Ը��������ֶ�
    let query = TableQuery::new(
        table_config,
        vec!["admin".to_string()],
        Some(Arc::new(pool)),
    );

    let mut update_data = HashMap::new();
    update_data.insert("name".to_string(), serde_json::json!("����"));
    update_data.insert("email".to_string(), serde_json::json!("lisi@example.com"));

    let result = query
        .where_eq("id", serde_json::json!(user_id))
        .unwrap()
        .update(update_data)
        .await;
    assert!(result.is_ok(), "admin ��ɫӦ�ÿ���д�������ֶ�");
}

