#[tokio::test]
#[ignore] // ��Ҫ Docker ����
async fn test_soft_delete() {
    let (pool, db) = setup_test_env!();

    // �������Ա������ɾ���ֶΣ�
    create_test_products_table(&db).await.unwrap();

    let table_config = create_test_products_table_config();

    // 1. ʹ��ԭ�� SQL �����������
    db.execute("INSERT INTO test_products (name, price) VALUES ('��ƷA', 99.99)")
        .await
        .unwrap();

    // 2. ��ѯ���������
    let query = TableQuery::new(
        table_config.clone(),
        vec!["admin".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let products: Vec<TestProduct> = query
        .where_eq("name", serde_json::json!("��ƷA"))
        .unwrap()
        .select()
        .await
        .unwrap();

    assert_eq!(products.len(), 1, "Ӧ�ò�ѯ�� 1 ����¼");
    assert_eq!(products[0].name, "��ƷA");
    assert_eq!(products[0].deleted_at, None, "deleted_at Ӧ��Ϊ null");

    let product_id = products[0].id;

    // 3. ִ����ɾ����ʵ������ UPDATE deleted_at��
    let query = TableQuery::new(
        table_config.clone(),
        vec!["admin".to_string()],
        Some(Arc::new(pool.clone())),
    );

    let affected = query
        .where_eq("id", serde_json::json!(product_id))
        .unwrap()
        .delete()
        .await
        .unwrap();

    assert_eq!(affected, 1, "��ɾ��Ӧ��Ӱ�� 1 ��");

    // 4. ��֤��ɾ���������¼��Ȼ���ڣ��� deleted_at ��Ϊ null
    let query = TableQuery::new(
        table_config,
        vec!["admin".to_string()],
        Some(Arc::new(pool)),
    );

    let products: Vec<TestProduct> = query
        .where_eq("id", serde_json::json!(product_id))
        .unwrap()
        .select()
        .await
        .unwrap();

    assert_eq!(products.len(), 1, "��¼Ӧ����Ȼ����");
    assert!(products[0].deleted_at.is_some(), "deleted_at Ӧ�ò�Ϊ null");
    assert!(
        products[0].deleted_at.unwrap() > 0,
        "deleted_at Ӧ����һ����Ч��ʱ���"
    );
}

