/// �����û��ṹ
#[derive(Debug, Clone, Serialize, Deserialize, sqlx::FromRow, PartialEq)]
struct TestUser {
    id: i64,
    name: String,
    email: String,
    age: i32,
    status: String,
}

/// ���Բ�Ʒ�ṹ��������ɾ�����ԣ�
